-- 제공 생성기의 시간대 없는 승인 시각은 KST 업무 시각으로 해석하여 UTC로 저장한다.
UPDATE card_transaction SET approved_at = DATEADD('HOUR', -9, approved_at),
    canceled_at = DATEADD('HOUR', -9, canceled_at);
UPDATE card_transaction SET original_amount = amount, exchange_rate = 1 WHERE currency = 'KRW';
UPDATE subscription SET original_amount = amount WHERE currency = 'KRW';

-- 월별 이용실적은 승인 내역에서 집계 (승인 건만)
SELECT card_id, FORMATDATETIME(DATEADD('HOUR', 9, approved_at), 'yyyy-MM'), SUM(amount), COUNT(*), 0
FROM card_transaction
WHERE status = 'APPROVED'
GROUP BY card_id, FORMATDATETIME(DATEADD('HOUR', 9, approved_at), 'yyyy-MM');





